query sp4e_racing_pmPool($date: String, $venueCode: String, $oddsTypes: [OddsType], $raceNo: Int) {
    raceMeetings(date: $date, venueCode: $venueCode)
    {
      pmPools(oddsTypes: $oddsTypes, raceNo: $raceNo) {
        id
        status
        sellStatus
        oddsType
        lastUpdateTime
        oddsLastUpdateTime
        guarantee
        minTicketCost
        name_en
        name_ch
        leg {
          number
          races
        }
        cWinSelections {
          composite
          name_ch
          name_en
          starters
        }
        oddsNodes {
          combString
          oddsValue
          hotFavourite
          oddsDropValue
          bankerOdds {
            combString
            oddsValue
          }
        }
      }
    }
}
